        <Link to="/rieng/thiet-lap/nguon-quet" className={pathname.endsWith('/nguon-quet') ? 'active' : undefined} aria-current={pathname.endsWith('/nguon-quet') ? 'page' : undefined}>Nguồn quét <span className="nav-beta">BETA</span></Link>
